<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api, action } from '../api'
const items=ref<any[]>([]),profiles=ref<any[]>([]),dialog=ref(false),editId=ref(''),form=reactive({name:'',description:'',extraction_profile_id:''})
async function load(){[items.value,profiles.value]=await Promise.all([api('/admin/knowledge-bases'),api('/admin/model-profiles')])}
onMounted(()=>action(load))
function edit(k?:any){editId.value=k?.id||'';Object.assign(form,k?{name:k.name,description:k.description,extraction_profile_id:k.extraction_profile_id}:{name:'',description:'',extraction_profile_id:''});dialog.value=true}
async function save(){await action(async()=>{await api('/admin/knowledge-bases'+(editId.value?'/'+editId.value:''),editId.value?'PUT':'POST',{...form,extraction_profile_id:form.extraction_profile_id||null});dialog.value=false;await load()})}
async function remove(id:string){try{await ElMessageBox.confirm('删除知识库前需要解除所有应用绑定。','删除知识库');await action(async()=>{await api('/admin/knowledge-bases/'+id,'DELETE');await load()})}catch{}}
</script>
<template><section class="page"><div class="page-eyebrow">ADMINISTRATION / KNOWLEDGE</div><div class="page-title"><div><h1>知识库</h1><p class="muted">选择知识库，点击“上传资料”导入教材、课件或习题。</p></div><el-button type="primary" @click="edit()">＋ 创建知识库</el-button></div><div class="kb-list"><article v-for="k in items" :key="k.id" class="panel kb-row"><div class="kb-icon">▤</div><div class="kb-info"><router-link :to="'/admin/knowledge-bases/'+k.id"><h3>{{k.name}} ↗</h3></router-link><p class="muted">{{k.description}}</p><el-tag :type="k.current_release_id?'success':'info'" size="small">{{k.current_release_id?'已有发布版本':'尚未发布'}}</el-tag><small class="muted"> · 修订 {{k.revision}}</small></div><router-link class="el-button el-button--primary is-plain" :to="{path:'/admin/knowledge-bases/'+k.id,query:{tab:'documents'}}">上传资料</router-link><el-button @click="edit(k)">配置</el-button><el-button @click="remove(k.id)">删除</el-button></article></div><el-empty v-if="!items.length" description="建立知识库，再上传教材、课件或习题"/><el-dialog v-model="dialog" :title="editId?'编辑知识库':'创建知识库'" width="min(560px, 95vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="默认语义切分模型"><el-select v-model="form.extraction_profile_id" clearable placeholder="选择生成模型" class="full-width"><el-option v-for="p in profiles.filter(p=>p.purpose==='generation'&&p.provider!=='demo')" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><p class="muted">导入时选择语义切分会调用此模型，也可为单份文档指定其他模型。规则切分不调用模型；导入后可直接发布。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
